INSERT INTO `settings` VALUES (112,7,'faqs_json','[{\"q\":\"What are the loan terms?\",\"a\":\"Step one, you have to fill all your personal information required in the application and you need to have an ID card or any of equivalent identification and a bank account to apply for the loan.\"},{\"q\":\"How long does it take to apply for a loan each time?\",\"a\":\"From the time of registration, verification of personal information will be considered at the earliest and will continue till the final stage of delivery within 1 hour, please contact customer service staff for more specific information.\"},{\"q\":\"How to check loan?\",\"a\":\"You can visit (website) - (List of Loan Criteria) It usually takes 1-24 hours to get approved\"},{\"q\":\"How to get refund after credit line is approved?\",\"a\":\"After the loan is successful, the payment method will be deducted from your bank account on 15th of every month. If the balance is not enough to pay off, it will adversely affect your information and lead to bad debts in future.\"},{\"q\":\"How can I contact the service?\",\"a\":\"You can contact (Customer Service) Customer Service Contact Department Online Time 11:00AM - 11:00PM\"},{\"q\":\"Can I sign out of my account?\",\"a\":\"Monthly service that partially \\\"cancels your account\\\" information you enter for personal protection is limited to loan applications.\"}]',NULL,NULL);
